"""Snap clock times to a fixed step and label the rounded spans for payroll."""

from typing import Iterable, List

from hourglass.models import Span
from hourglass.parsing import format_span

# ---
def label_rounded_spans(spans: Iterable[Span], step_minutes: int) -> List[str]:
    """Round each start and end to the nearest step and label the span.

    Labels look like 09:00-17:15 (8h 15m). Halves round up. A span that rounds
    down to nothing raises ValueError, as does a step that does not divide 60.
    """
    _check_step(step_minutes)
    return [_label(_round_span(span, step_minutes)) for span in spans]

def _check_step(step_minutes: int) -> None:
    if step_minutes <= 0 or 60 % step_minutes != 0:
        raise ValueError(f"step must divide 60 evenly, got {step_minutes}")

def _round_span(span: Span, step_minutes: int) -> Span:
    start = _round_to_step(span.start, step_minutes)
    end = _round_to_step(span.end, step_minutes)
    if start >= end:
        raise ValueError(f"{format_span(span)} rounds to nothing")
    return Span(start, end)

def _round_to_step(minute: int, step_minutes: int) -> int:
    return (minute + step_minutes // 2) // step_minutes * step_minutes

def _label(span: Span) -> str:
    hours, minutes = divmod(span.minutes, 60)
    return f"{format_span(span)} ({hours}h {minutes}m)"

