# owner: platform
import unittest

from hourglass.parsing import parse_span
from hourglass.rounding import label_rounded_spans

class LabelTests(unittest.TestCase):
    def test_rounds_to_nearest_step(self):
        spans = [parse_span("09:02-17:14")]
        self.assertEqual(label_rounded_spans(spans, 15), ["09:00-17:15 (8h 15m)"])

    def test_halves_round_up(self):
        spans = [parse_span("09:05-10:05")]
        self.assertEqual(label_rounded_spans(spans, 10), ["09:10-10:10 (1h 0m)"])

    def test_exact_multiples_are_unchanged(self):
        spans = [parse_span("09:00-17:30")]
        self.assertEqual(label_rounded_spans(spans, 15), ["09:00-17:30 (8h 30m)"])

    def test_step_of_one_keeps_minutes(self):
        spans = [parse_span("09:03-10:07")]
        self.assertEqual(label_rounded_spans(spans, 1), ["09:03-10:07 (1h 4m)"])

    def test_end_of_day_is_allowed(self):
        spans = [parse_span("23:50-24:00")]
        self.assertEqual(label_rounded_spans(spans, 15), ["23:45-24:00 (0h 15m)"])

    def test_keeps_order_and_labels_each_span(self):
        spans = [parse_span("13:00-14:00"), parse_span("09:02-09:58")]
        self.assertEqual(
            label_rounded_spans(spans, 15),
            ["13:00-14:00 (1h 0m)", "09:00-10:00 (1h 0m)"]
        )

    def test_empty_list(self):
        self.assertEqual(label_rounded_spans([], 15), [])

class RoundsToNothingTests(unittest.TestCase):
    def test_span_that_collapses_raises(self):
        with self.assertRaises(ValueError):
            label_rounded_spans([parse_span("09:01-09:04")], 15)

    def test_collapse_in_a_later_span_raises(self):
        spans = [parse_span("09:00-10:00"), parse_span("11:01-11:04")]
        with self.assertRaises(ValueError):
            label_rounded_spans(spans, 15)

class StepTests(unittest.TestCase):
    def test_bad_steps_raise(self):
        for step in (0, -15, -1, 7, 25, 45, 120):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    label_rounded_spans([parse_span("09:00-10:00")], step)

    def test_bad_step_raises_even_with_no_spans(self):
        with self.assertRaises(ValueError):
            label_rounded_spans([], 0)

    def test_step_of_an_hour_is_allowed(self):
        spans = [parse_span("09:20-17:40")]
        self.assertEqual(label_rounded_spans(spans, 60), ["09:00-18:00 (9h 0m)"])
